def compile_topic(t):
    en = re.compile(r'\b(?:' + t[3] + r')\b', re.I)
    vi = [(re.compile(r'(?<![\wÀ-ỹ])' + re.escape(k) + r'(?![\wÀ-ỹ])'), len(k.split()), len(k)) for k in t[4]]
    return en, vi
C = {t[0]: compile_topic(t) for t in T}
ORDER = {t[0]: i for i, t in enumerate(T)}
def first(s, sep=';'):
    return re.split(r'[;；]', s or '')[0].strip()
def topic_of(h, vi, en, pos, strict=False):
    if h in MANUAL: return MANUAL[h]
    if pos and pos[0] in FUNC: return None
    if pos and set(pos) <= {'số từ','lượng từ','số lượng từ'}: return 'number'
    v1 = re.sub(r'\([^)]*\)', ' ', first(vi)).lower(); e1 = first(en)
    best = None
    for tid in ORDER:
        en_re, vi_res = C[tid]
        sv = max([(n, l) for rx, n, l in vi_res if rx.search(v1)], default=None)
        se = 1 if en_re.search(e1) else 0
        if not sv and not se: continue
        if strict and not (sv and se): continue
        # chặt hơn: chỉ một bên khớp thì từ khoá phải chiếm phần lớn nghĩa
        vlen = len(v1.strip()) or 1
        if sv and not se and sv[1] / vlen < 0.6: continue
        if se and not sv and len(re.findall(r'[A-Za-z]+', e1)) > 2: continue
        sc = (2 if sv and se else 1, sv[0] if sv else 0, sv[1] if sv else 0, -ORDER[tid])
        if best is None or sc > best[0]: best = (sc, tid)
    return best[1] if best else None
out = {'topics': [[t[0], t[1], t[2]] for t in T], 'w': {}, 'x': {}}
cnt = collections.Counter()
for L in range(1, 7):
    d = json.load(open(APP + f'data/dict{L}.json'))
    for r in json.load(open(APP + f'data/hsk{L}.json')):
        h, v = r[0], r[2]; k = r[5] if len(r) > 5 else h
        en, pos = d.get(k, ['', []])[0], d.get(k, ['', []])[1]
        t = topic_of(h, v, en, pos)
        if t: out['w'][k] = t; cnt[t] += 1
ext = json.load(open(APP + 'data/ext.json')); nx = 0
for L in ext:
    for a in ext[L]:
        if a[7] and a[7] <= 25000:   # chỉ từ mở rộng thông dụng
            t = topic_of(a[0], a[2], a[4], a[5], True)
            if t: out['x'][a[0]] = t; cnt[t] += 1; nx += 1
json.dump(out, open(APP + 'data/topics.json', 'w'), ensure_ascii=False, separators=(',', ':'))
